package it.polimi.ingsoft.mesos.server.controller.command;

/**
 * Base type for every element processed by a controller queue.
 *
 * <p>The server has one queue per controller level: pre-lobby, lobby, and game.
 * Those queues do not contain only network messages. They contain all the work
 * that a controller must process in order: client payloads routed by the
 * network layer and internal server commands generated by lifecycle code or by
 * another controller.
 *
 * <p>The common piece of information is the {@code sessionId}. It is the stable
 * runtime identity used to ask {@code ServerSessionRegistry} for the current
 * listener, nickname, lobby, or game. Commands should not duplicate those
 * derived values.
 */
public interface QueuedCommand {
    /**
     * Retrieves the unique session identifier associated with this queued command.
     *
     * <p>The session ID is used by controllers to resolve session-scoped resources
     * (such as the player's nickname, network listener, or their corresponding
     * player instance in a match) from the central registry.
     *
     * @return the unique session identifier, or {@code null} if the command is
     *         system-wide and not initiated by or bound to a specific client session
     */
    String getSessionId();
}
